<style>

.wordmark path {
  fill: currentColor;
  transition: fill 500ms ease-out; /* softens a mid-wave mouse-out */
}

.wordmark:hover path,
.wordmark:focus-visible path {
  animation: wordmark-flash 500ms ease-out infinite;
  animation-delay: calc(var(--i) * 50ms);
}

@keyframes wordmark-flash {
  0%   { fill: currentColor; }
  35%  { fill: var(--graph-accent); }
  65%  { fill: var(--graph-accent); }
  100% { fill: currentColor; }
}

@media (prefers-reduced-motion: reduce) {
  .wordmark:hover path { animation: none; fill: var(--graph-accent); }
}

</style>